content:
Roda esse comando único no terminal do servidor — aplica o patch e dá o restart:

```bash
cat > /tmp/patch_topic_id.js <<'JSEOF'
const fs = require('fs');
const path = '/root/openclaw/bridge.cjs';
let src = fs.readFileSync(path, 'utf8');
if (src.includes('/topic_id')) { console.log('já patched'); process.exit(0); }
const marker = '  log("info", `Mensagem de ${msg.from.first_name}${threadId ? ` (tópico ${threadId})` : ""}: ${summary}`);\n\n  try {';
const replacement = [
  '  log("info", `Mensagem de ${msg.from.first_name}${threadId ? ` (tópico ${threadId})` : ""}: ${summary}`);',
  '',
  '  const txt = (msg.text || "").trim();',
  '  if (txt === "/topic_id" || txt === "/id" || txt.startsWith("/topic_id@") || txt.startsWith("/id@")) {',
  '    const reply = `chat_id: \\`${chatId}\\`\\nthread_id: \\`${threadId ?? "(nenhum · não é tópico)"}\\``;',
  '    await sendMessage(chatId, reply, threadId);',
  '    return;',
  '  }',
  '',
  '  try {'
].join('\n');
if (!src.includes(marker)) { console.error('marker não encontrado'); process.exit(1); }
fs.writeFileSync(path, src.replace(marker, replacement));
console.log('patched ✓');
JSEOF
node /tmp/patch_topic_id.js && pkill -f 'node bridge.cjs' ; sleep 1 && cd /root/openclaw && nohup node bridge.cjs > bot.log 2>&1 & echo "bot rodando"
```

Quando rodar:
1. Adiciona o Guia (bot) no grupo como admin do tópico
2. Manda `/topic_id` dentro do tópico
3. Ele responde com `chat_id` e `thread_id` em code block — copia e me passa

Beleza. Pra isso preciso 2 mudanças no `bridge.cjs`:

1. Ler `ALLOWED_GROUP_IDS` do `.env` (lista de chat_ids separados por vírgula)
2. Aceitar mensagens de qualquer membro nesses grupos (mantém DM bloqueado pra OWNER)

Comando único pro terminal — aplica patch + restarta:

```bash
cat > /tmp/patch_whitelist.js <<'JSEOF'
const fs = require('fs');
const p = '/root/openclaw/bridge.cjs';
let s = fs.readFileSync(p, 'utf8');

// 1. Adiciona const ALLOWED_GROUPS após OWNER_ID, se ainda não existe
if (!s.includes('ALLOWED_GROUPS')) {
  const mk1 = 'const OWNER_ID      = String(process.env.OWNER_CHAT_ID || "");';
  const rp1 = mk1 + '\nconst ALLOWED_GROUPS = (process.env.ALLOWED_GROUP_IDS || "").split(",").map(x => x.trim()).filter(Boolean);';
  if (!s.includes(mk1)) { console.error('marker 1 não encontrado'); process.exit(1); }
  s = s.replace(mk1, rp1);
}

// 2. Substitui whitelist em handleMessage
const mk2 = [
  '  // Whitelist estrita',
  '  const isOwner = chatId === OWNER_ID || String(msg.from?.id) === OWNER_ID;',
  '  if (!isOwner) {',
  '    log("info", `Ignorando mensagem de chat ${chatId} (não é OWNER)`);',
  '    return;',
  '  }'
].join('\n');
const rp2 = [
  '  // Whitelist: DM do OWNER OU grupo autorizado (qualquer membro)',
  '  const isOwner = chatId === OWNER_ID || String(msg.from?.id) === OWNER_ID;',
  '  const isAllowedGroup = ALLOWED_GROUPS.includes(chatId);',
  '  if (!isOwner && !isAllowedGroup) {',
  '    log("info", `Ignorando mensagem de chat ${chatId} from ${msg.from?.id} (não autorizado)`);',
  '    return;',
  '  }'
].join('\n');
if (!s.includes(rp2.split('\n')[0])) {
  if (!s.includes(mk2)) { console.error('marker 2 não encontrado'); process.exit(1); }
  s = s.replace(mk2, rp2);
}

fs.writeFileSync(p, s);
console.log('patched ✓');
JSEOF
node /tmp/patch_whitelist.js && pkill -f 'node bridge.cjs' ; sleep 1 && cd /root/openclaw && nohup node bridge.cjs > bot.log 2>&1 & echo "bot rodando"
```

Depois, quando descobrir o `chat_id` do grupo (via `/topic_id`), edita o `.env`:

```bash
echo "ALLOWED_GROUP_IDS=-1003923758478" >> /root/openclaw/.env
```

(usa o chat_id real, com `-100` na frente — esse é só palpite baseado no que mandou)

E restarta de novo:

```bash
pkill -f 'node bridge.cjs' ; sleep 1 && cd /root/openclaw && nohup node bridge.cjs > bot.log 2>&1 & echo "bot rodando"
```

Pode rodar em qualquer ordem (whitelist primeiro, ou /topic_id primeiro). Faz sentido?
